"use strict";
(()=>{const L=window.Lab;if(!L||!L.$('forced-lab'))return;
L.init(['input','damping','frequency','position','velocity'],()=>{const mode=L.$('input').value,b=L.range('damping'),w=L.range('frequency'),x0=L.range('position'),v0=L.range('velocity'),res=mode==='cosine'&&b===0&&w===2;let xp,d0,p0;if(mode==='step'){xp=t=>.25;p0=.25;d0=0;}else if(res){xp=t=>t*Math.sin(w*t)/(2*w);p0=0;d0=0;}else{const a=4-w*w,den=a*a+b*b*w*w;xp=t=>(a*Math.cos(w*t)+b*w*Math.sin(w*t))/den;p0=a/den;d0=b*w*w/den;}const h=t=>L.homogeneous(b,x0-p0,v0-d0,t).x,total=t=>xp(t)+h(t);const max=Math.max(.4,...Array.from({length:241},(_,i)=>i/30).flatMap(t=>[Math.abs(xp(t)),Math.abs(h(t)),Math.abs(total(t))]))*1.12;L.plot(L.$('drawing'),[{fn:xp,color:'#cf604b'},{fn:h,color:'#172a45',dash:'7 5'},{fn:total}],{xMax:8,yMin:-max,yMax:max,yLabel:'位置 x（m）；三曲線同一尺度'});L.text('result-primary',L.fmt(total(1))+' m');L.text('result-secondary',mode==='step'&&b>0?'0.25 m':res?'無有限穩態':b===0?'自然項不消失':'同頻正弦');L.text('feedback','修正的起點是 '+L.fmt(x0-p0)+' m、速度 '+L.fmt(v0-d0)+' m/s，所以相加後回到指定的 '+L.fmt(x0)+' m、'+L.fmt(v0)+' m/s。'+(res?'此處走無阻尼共振公式 t sin(2t)/4，振幅隨時間增長；不拿零分母硬除。':b===0?'無阻尼時，齊次修正不會衰減，不能只保留特解。':'阻尼大於零時，齊次修正逐漸衰減，留下外力持續維持的部分。')+' 縱軸依三條曲線共同縮放。');});})();
